//! Bounded local technical events, never recordings, transcripts, prompts,
//! profile/device names, endpoints or credentials.
use serde::Serialize;
use std::{
    fs::{self, OpenOptions},
    io::Write,
    path::{Path, PathBuf},
    sync::Mutex,
    time::{SystemTime, UNIX_EPOCH},
};

pub struct AudioDiagnostics {
    path: PathBuf,
    lock: Mutex<()>,
}

#[derive(Serialize)]
struct Entry<'a> {
    unix_ms: u128,
    version: &'static str,
    event: &'static str,
    reply_chars: usize,
    heard_chars: usize,
    // Only fixed messages generated by our native audio worker, never a
    // provider/network error or any part of a conversation.
    audio_error: Option<&'a str>,
}

impl AudioDiagnostics {
    pub fn new(directory: &Path) -> Self {
        Self {
            path: directory.join("audio-events.log"),
            lock: Mutex::new(()),
        }
    }

    pub fn record(
        &self,
        event: &'static str,
        reply_chars: usize,
        heard_chars: usize,
        audio_error: Option<&str>,
    ) {
        let Ok(_guard) = self.lock.lock() else { return };
        if fs::metadata(&self.path).is_ok_and(|m| m.len() >= 128 * 1024) {
            let previous = self.path.with_file_name("audio-events.previous.log");
            let _ = fs::remove_file(&previous);
            if fs::rename(&self.path, previous).is_err() {
                return;
            }
        }
        let entry = Entry {
            unix_ms: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis(),
            version: env!("CARGO_PKG_VERSION"),
            event,
            reply_chars,
            heard_chars,
            audio_error,
        };
        if let Ok(mut file) = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)
            && let Ok(line) = serde_json::to_string(&entry)
        {
            let _ = writeln!(file, "{line}");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn events_survive_restart_and_rotate_without_conversation_content() {
        let dir = tempfile::tempdir().unwrap();
        let log = AudioDiagnostics::new(dir.path());
        log.record("capture_gap", 995, 790, None);
        let entry: serde_json::Value =
            serde_json::from_str(&fs::read_to_string(&log.path).unwrap()).unwrap();
        assert_eq!(entry["reply_chars"], 995);
        assert_eq!(entry["heard_chars"], 790);
        assert!(entry["audio_error"].is_null());
        let reopened = AudioDiagnostics::new(dir.path());
        reopened.record("audio_started", 0, 0, None);
        assert_eq!(fs::read_to_string(&log.path).unwrap().lines().count(), 2);
        fs::write(&log.path, vec![b' '; 128 * 1024]).unwrap();
        log.record("audio_failed", 0, 0, None);
        assert_eq!(
            fs::metadata(dir.path().join("audio-events.previous.log"))
                .unwrap()
                .len(),
            128 * 1024
        );
        assert_eq!(fs::read_to_string(&log.path).unwrap().lines().count(), 1);
    }
}
